const e="st-gregorios-sharjah-sunday-school",u=2026,n="Built from the unit's 2026 Annual Competitions circular (7 pages: schedule, age grouping, syllabus, rules). The circular does not print entry fees, venue, address, contact people, prizes, or time limits for Bible Reading and the Bible Quiz, and refers to a separate Handbook for the details of Solo, Extempore, Drawing, Memory Verse, Action Song and Bible Reading (only the points printed in the circular are captured). The online registration form link is not printed. The Malayalam elocution verses are printed in damaged text; the English translation printed beside them is used.",o={Title:"Rules & Criteria",Subtitle:"Sunday School annual competitions 2026 - unit level, with qualifiers going on to the UAE level",NoticeTitle:"Please Read Before Registering",Notice:"Last date to register is {{RegistrationDeadline}}. Check your details before you submit: wrong details can lead to disqualification.",Notes:["Age is counted as on {{AgeCutoffDate}}.","The final continuous bell starts negative marking. Going over the time limit is not a disqualification."],Sections:[{Key:"general",Title:"General rules",Items:["Going over the time limit does not cause disqualification. It causes negative marking in proportion to the extra time taken after the final bell."]},{Key:"eligibility",Title:"Who can enter",Items:["Sub-Juniors are below 8 years, born after 1 October 2018.","Juniors are 8 to 11 years, born between 1 October 2015 and 30 September 2018.","Intermediates are 11 to 14 years, born between 1 October 2012 and 30 September 2015.","Seniors are 14 to 18 years, born between 1 October 2008 and 30 September 2012.","The qualifying age is counted as on {{AgeCutoffDate}}.","A participant may enter only the events he or she plans to take part in and is eligible for.","Do not submit more than one entry for the same participant and the same event.","A participant who qualifies for the UAE level needs at least 60 percent Sunday School attendance as on {{AttendanceDate}}.","If a qualified participant loses eligibility, the next position holder from the winners list represents the unit at the UAE level."]},{Key:"registration",Title:"How to register",Items:["Register for the unit level competitions through the online form. The form is shared on the class WhatsApp groups and on the Sunday School page of the church website.","Check that all details are correct before final submission. Wrong data can lead to disqualification of the participant.","For Malayalam Group Song, the group leader must enrol the names of all four members together. Individual registration is not allowed.","The last date for registration is {{RegistrationDeadline}}."]},{Key:"dates",Title:"Competition dates",Items:["{{DayColouring}}, {{TimeAfternoon}}: Colouring (Sub-Juniors); Drawing & Colouring and Memory Verse Writing (Juniors, Intermediates, Seniors).","{{DayAction}}, {{TimeAfternoon}}: Action Song (Sub-Juniors, Juniors); Story Telling (Juniors); Bible Reading (Juniors, Intermediates, Seniors).","{{DayElocution}}, {{TimeMorning}}: English Elocution (all groups); Malayalam Elocution (Intermediates, Seniors); Extempore Speech (Intermediates and Seniors together).","{{DaySong}}, {{TimeMorning}}: English Solo and Malayalam Solo (Sub-Juniors and Juniors together; Intermediates and Seniors with separate Girls and Boys competitions); Malayalam Group Song (all groups).","{{DayQuiz}}, {{TimeQuizStart}}: Bible Quiz (Juniors); Quiz on Bible, Faith and History (Intermediates and Seniors together)."]},{Key:"levels",Title:"Qualifying to the UAE level",Items:["The first two position winners in English Solo and Malayalam Solo qualify for the UAE Zonal Competitions ({{ZonalMonth}}).","The first two position winners in English Elocution qualify for the UAE Zonal Competitions. The elocution topic at UAE level is the same as at unit level.","The first two position winners in Extempore Speech qualify for the UAE Zonal Competitions.","The first four position holders in the Quiz for Intermediates and Seniors qualify for the UAE level competition ({{ZonalMonth}}).","If at least 3 teams take part in a Group Song category, the first prize group of that category qualifies for the UAE level.","If fewer than 3 teams take part in a Group Song category, the first four position winners in Malayalam Solo, boys and girls together, represent the unit in the Group Song at the UAE level.","Song selection and training for the UAE level are guided by the assigned Sunday School teachers.","In a tie for a UAE level place, the choice is made by lot straight after the results are announced, in front of the judges, Sunday School officials and the Vicar or Co-Vicar.","These competitions are held only at unit level: Malayalam Elocution, Juniors Quiz, Colouring, Drawing & Colouring, Memory Verse Writing, Action Song, Story Telling and Bible Reading."]},{Key:"teams",Title:"Teams",Items:["Malayalam Group Song is only for groups of four."]},{Key:"other",Title:"Other information",Items:["The circular says other details for Malayalam Solo, English Solo, Extempore Speech, Drawing & Colouring, Memory Verse Writing, Action Song, Bible Reading and others are in the Sunday School Handbook."]}],Documents:[{Title:"Memory verse list (500 verses)",Url:"https://www.gulfparumala.com/cultural_competitions/Ry"},{Title:"Annual Competitions 2026 circular",Url:"https://gulfparumala.com/storage/datafolder/ckeditorimage/Competition%20Info-Rev_1773775026.pdf"}]},t=[],i=[{AgeGroup:"Sub-Juniors",Source:"Competition Age Grouping",Sections:{About:null,TimeAndFormat:null,Rules:["Qualifying age is below 8, born after 1 October 2018 (age as on {{AgeCutoffDate}})."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Qualifying age is below 8, born after 1 October 2018 (age as on {{AgeCutoffDate}}).`},{AgeGroup:"Juniors",Source:"Competition Age Grouping",Sections:{About:null,TimeAndFormat:null,Rules:["Qualifying age is 8 to 11, born between 1 October 2015 and 30 September 2018 (age as on {{AgeCutoffDate}})."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Qualifying age is 8 to 11, born between 1 October 2015 and 30 September 2018 (age as on {{AgeCutoffDate}}).`},{AgeGroup:"Intermediates",Source:"Competition Age Grouping",Sections:{About:null,TimeAndFormat:null,Rules:["Qualifying age is 11 to 14, born between 1 October 2012 and 30 September 2015 (age as on {{AgeCutoffDate}})."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Qualifying age is 11 to 14, born between 1 October 2012 and 30 September 2015 (age as on {{AgeCutoffDate}}).`},{AgeGroup:"Seniors",Source:"Competition Age Grouping",Sections:{About:null,TimeAndFormat:null,Rules:["Qualifying age is 14 to 18, born between 1 October 2008 and 30 September 2012 (age as on {{AgeCutoffDate}})."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Qualifying age is 14 to 18, born between 1 October 2008 and 30 September 2012 (age as on {{AgeCutoffDate}}).`}],a=JSON.parse(`[{"Title":"Colouring","Source":"Rules 2, Colouring","Sections":{"About":["For Sub-Juniors only."],"TimeAndFormat":["Time limit is 1 hour."],"Rules":["The picture is provided. Participants bring their own colouring materials.","Held at unit level only."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- For Sub-Juniors only.\\n\\n## Time and format\\n- Time limit is 1 hour.\\n\\n## Rules\\n- The picture is provided. Participants bring their own colouring materials.\\n- Held at unit level only."},{"Title":"Drawing & Colouring","Source":"Rules 2, Drawing & Colouring","Sections":{"About":["For Juniors, Intermediates and Seniors."],"TimeAndFormat":["Time limit is 1.5 hours."],"Rules":["A Bible theme is provided. Students draw and shade or colour it.","Participants bring their own drawing and colouring materials. Drawing sheets are provided.","Held at unit level only."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- For Juniors, Intermediates and Seniors.\\n\\n## Time and format\\n- Time limit is 1.5 hours.\\n\\n## Rules\\n- A Bible theme is provided. Students draw and shade or colour it.\\n- Participants bring their own drawing and colouring materials. Drawing sheets are provided.\\n- Held at unit level only."},{"Title":"Memory Verse Writing","Source":"Rules 2, Memory Verse Writing","Sections":{"About":["For Juniors, Intermediates and Seniors."],"TimeAndFormat":["Time limit is 1 hour for Juniors and 1.5 hours for Intermediates and Seniors."],"Rules":["Choose verses mainly from the list of 500 memory verses on the church website.","Verses outside the list are allowed, but only 3 verses from any one chapter. If more are written, only the first 3 count.","Number the verses and write them clearly with the Bible reference.","Repeating a verse gives negative marks.","Held at unit level only."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- For Juniors, Intermediates and Seniors.\\n\\n## Time and format\\n- Time limit is 1 hour for Juniors and 1.5 hours for Intermediates and Seniors.\\n\\n## Rules\\n- Choose verses mainly from the list of 500 memory verses on the church website.\\n- Verses outside the list are allowed, but only 3 verses from any one chapter. If more are written, only the first 3 count.\\n- Number the verses and write them clearly with the Bible reference.\\n- Repeating a verse gives negative marks.\\n- Held at unit level only."},{"Title":"Action Song","Source":"Rules 2, Action Song","Sections":{"About":["For Sub-Juniors and Juniors."],"TimeAndFormat":["Time limit is strictly 3 minutes."],"Rules":null,"Allowed":["The song can be in English or Malayalam.","Props may be used if needed, but minimal.","Costumes that suit the characters shown."],"NotAllowed":["Songs that are not Christian action songs.","Movements that overwhelm the singing.","Moving off the stage area.","Costumes that turn it into a fancy dress competition."],"Judging":["Language skill, delivery and presentation: well-coordinated and creative actions, rhythm, timing, tempo, confidence, voice quality, and how well the theme works."],"Points":null,"Notes":["Only one microphone is provided.","Held at unit level only."]},"Markdown":"## About this competition\\n- For Sub-Juniors and Juniors.\\n\\n## Time and format\\n- Time limit is strictly 3 minutes.\\n\\n## Allowed\\n- The song can be in English or Malayalam.\\n- Props may be used if needed, but minimal.\\n- Costumes that suit the characters shown.\\n\\n## Not allowed\\n- Songs that are not Christian action songs.\\n- Movements that overwhelm the singing.\\n- Moving off the stage area.\\n- Costumes that turn it into a fancy dress competition.\\n\\n## Judging\\n- Language skill, delivery and presentation: well-coordinated and creative actions, rhythm, timing, tempo, confidence, voice quality, and how well the theme works.\\n\\n## Notes for participants\\n- Only one microphone is provided.\\n- Held at unit level only."},{"Title":"Story Telling","Source":"Rules 2, Story Telling; Syllabus 3","Sections":{"About":["For Juniors only. The story for the year is {{StoryTopic}}."],"TimeAndFormat":["Time limit is strictly 4 minutes."],"Rules":["Only Biblical stories on the given topic are allowed. The Bible text may be shortened to fit the time.","The story must be memorised, not read.","No props. The performer stays in one place.","Held at unit level only."],"Allowed":null,"NotAllowed":null,"Judging":["Content: how well the story follows the Bible passage and is applied to life.","Clarity: pronunciation and voice strength.","Delivery and presentation: appearance, poise, confidence, style, voice modulation, facial expression, memory, audience contact, body language, gestures, enthusiasm and overall effect."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- For Juniors only. The story for the year is {{StoryTopic}}.\\n\\n## Time and format\\n- Time limit is strictly 4 minutes.\\n\\n## Rules\\n- Only Biblical stories on the given topic are allowed. The Bible text may be shortened to fit the time.\\n- The story must be memorised, not read.\\n- No props. The performer stays in one place.\\n- Held at unit level only.\\n\\n## Judging\\n- Content: how well the story follows the Bible passage and is applied to life.\\n- Clarity: pronunciation and voice strength.\\n- Delivery and presentation: appearance, poise, confidence, style, voice modulation, facial expression, memory, audience contact, body language, gestures, enthusiasm and overall effect."},{"Title":"Bible Reading","Source":"Rules 2, Bible Reading","Sections":{"About":["For Juniors, Intermediates and Seniors."],"TimeAndFormat":null,"Rules":["The portion to read is drawn by lot.","The Bible used is the NRSV (Catholic Edition), provided at the venue.","The portion can be from the Old or the New Testament.","Held at unit level only."],"Allowed":null,"NotAllowed":null,"Judging":["Speed in finding the portion, clarity of reading, how well the message is conveyed, presentation and similar points."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- For Juniors, Intermediates and Seniors.\\n\\n## Rules\\n- The portion to read is drawn by lot.\\n- The Bible used is the NRSV (Catholic Edition), provided at the venue.\\n- The portion can be from the Old or the New Testament.\\n- Held at unit level only.\\n\\n## Judging\\n- Speed in finding the portion, clarity of reading, how well the message is conveyed, presentation and similar points."},{"Title":"Elocution","Source":"Rules 2, English and Malayalam Elocution; Syllabus 1-2","Sections":{"About":["English Elocution is for all groups. Malayalam Elocution is for Intermediates and Seniors and is held at unit level only. Rules and time limits are the same for both."],"TimeAndFormat":["Sub-Juniors and Juniors: 4 minutes. Warning double bell at 3 minutes, final continuous bell at 4 minutes 1 second.","Intermediates and Seniors: 5 minutes. Warning double bell at 4 minutes, final continuous bell at 5 minutes 1 second.","The final continuous bell starts negative marking."],"Rules":null,"Allowed":null,"NotAllowed":["Looking at any material while speaking leads to disqualification."],"Judging":null,"Points":null,"Notes":["English topics: Sub-Juniors - Forgiveness; Juniors - Matthew 18:4; Intermediates - Ephesians 4:26; Seniors - Galatians 2:20.","Malayalam topics: Intermediates - Luke 1:37; Seniors - Colossians 3:2."]},"Markdown":"## About this competition\\n- English Elocution is for all groups. Malayalam Elocution is for Intermediates and Seniors and is held at unit level only. Rules and time limits are the same for both.\\n\\n## Time and format\\n- Sub-Juniors and Juniors: 4 minutes. Warning double bell at 3 minutes, final continuous bell at 4 minutes 1 second.\\n- Intermediates and Seniors: 5 minutes. Warning double bell at 4 minutes, final continuous bell at 5 minutes 1 second.\\n- The final continuous bell starts negative marking.\\n\\n## Not allowed\\n- Looking at any material while speaking leads to disqualification.\\n\\n## Notes for participants\\n- English topics: Sub-Juniors - Forgiveness; Juniors - Matthew 18:4; Intermediates - Ephesians 4:26; Seniors - Galatians 2:20.\\n- Malayalam topics: Intermediates - Luke 1:37; Seniors - Colossians 3:2."},{"Title":"Extempore Speech","Source":"Rules 2, Extempore Speech","Sections":{"About":["For Intermediates and Seniors only, held together."],"TimeAndFormat":["Time limit is 5 minutes. Warning double bell at 4 minutes, final continuous bell at 5 minutes 1 second. The final bell starts negative marking.","The topic is given to each participant separately 10 minutes before the performance."],"Rules":["A participant must speak for at least 1 minute on the topic to qualify for a prize."],"Allowed":["During the 10 minutes of preparation, only the Holy Bible provided by the officials may be used."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- For Intermediates and Seniors only, held together.\\n\\n## Time and format\\n- Time limit is 5 minutes. Warning double bell at 4 minutes, final continuous bell at 5 minutes 1 second. The final bell starts negative marking.\\n- The topic is given to each participant separately 10 minutes before the performance.\\n\\n## Rules\\n- A participant must speak for at least 1 minute on the topic to qualify for a prize.\\n\\n## Allowed\\n- During the 10 minutes of preparation, only the Holy Bible provided by the officials may be used."},{"Title":"Solo","Source":"Rules 2, English Solo and Malayalam Solo","Sections":{"About":["English Solo and Malayalam Solo, all groups."],"TimeAndFormat":["Time limit is strictly 3 minutes. Warning double bell at 2 minutes 50 seconds, final continuous bell at 3 minutes 1 second. The final bell starts negative marking."],"Rules":["Intermediates and Seniors have separate competitions for male and female participants.","Sub-Juniors and Juniors compete together."],"Allowed":["Semi-classical songs."],"NotAllowed":["Songs that are not Christian.","Classical songs."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- English Solo and Malayalam Solo, all groups.\\n\\n## Time and format\\n- Time limit is strictly 3 minutes. Warning double bell at 2 minutes 50 seconds, final continuous bell at 3 minutes 1 second. The final bell starts negative marking.\\n\\n## Rules\\n- Intermediates and Seniors have separate competitions for male and female participants.\\n- Sub-Juniors and Juniors compete together.\\n\\n## Allowed\\n- Semi-classical songs.\\n\\n## Not allowed\\n- Songs that are not Christian.\\n- Classical songs."},{"Title":"Group Song","Source":"Rules 2, Malayalam Group Song; Syllabus 4","Sections":{"About":["Malayalam Group Song, all groups, in teams of four."],"TimeAndFormat":["Time limit and other rules are the same as Malayalam Solo (3 minutes)."],"Rules":["Only liturgical songs from the syllabus are allowed.","Uniform is compulsory: black and white, or full white.","Sub-Juniors: any song from the Holy Qurbana (no special songs), from Visudha Qurbaanakramam.","Juniors: any song used for the Kaimuthu, from Visudha Qurbaanakramam.","Intermediates: any song from the Baptismal Service, from Koodasakramangal.","Seniors: any song from the Mid-Lent Service (Andu Thaksa), or any song of Maundy Thursday from Evening Vespers to Ninth Hour, excluding the special songs of the Maundy Thursday Holy Qurbana and the Feet Washing Service (Kashtanubhava Azhchayile Namkarakramam)."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Malayalam Group Song, all groups, in teams of four.\\n\\n## Time and format\\n- Time limit and other rules are the same as Malayalam Solo (3 minutes).\\n\\n## Rules\\n- Only liturgical songs from the syllabus are allowed.\\n- Uniform is compulsory: black and white, or full white.\\n- Sub-Juniors: any song from the Holy Qurbana (no special songs), from Visudha Qurbaanakramam.\\n- Juniors: any song used for the Kaimuthu, from Visudha Qurbaanakramam.\\n- Intermediates: any song from the Baptismal Service, from Koodasakramangal.\\n- Seniors: any song from the Mid-Lent Service (Andu Thaksa), or any song of Maundy Thursday from Evening Vespers to Ninth Hour, excluding the special songs of the Maundy Thursday Holy Qurbana and the Feet Washing Service (Kashtanubhava Azhchayile Namkarakramam)."},{"Title":"Bible Quiz","Source":"Rules 2, Quiz; Syllabus 5","Sections":{"About":["Juniors have their own quiz, held at unit level only. Intermediates and Seniors compete together."],"TimeAndFormat":null,"Rules":["Juniors: Old Testament - Leviticus, Job, Ezekiel. New Testament - Luke, Galatians, Ephesians.","Intermediates and Seniors: Old Testament - Leviticus, Job, Ezekiel. New Testament - Luke, Galatians, Ephesians, Philippians, Colossians, 1 Thessalonians, 2 Thessalonians.","Intermediates and Seniors: Church History - AD 1654 to AD 1816, both years included, from 'The Orthodox Church of India' by David Daniel.","Intermediates and Seniors: Worship and Sacraments - Sacraments of Anointing of the Sick and Qandilo, from MOC Publications books (Koodaasa Kramangal, Order of the Sacraments, Kantheela Susroosha kramam, Order of the Anointing of the sick known as the service of Qandilo, Susroosha samvidhaana sahaayi) and Sunday School Textbook (OSSAE) Class XII ND Chapter 5.","Intermediates and Seniors: Feasts and Church Calendar - Epiphany (Denaha), from Aandu Thaksa - Perunnal Susroosha kramam, Order of the Prayers of the Major Feasts, Susroosha samvidhaana sahaayi (MOC Publications) and Sunday School Textbook (OSSAE) Class XII ND Chapter 9.","Reference Bible: The Holy Bible (NRSV Catholic Edition)."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Juniors have their own quiz, held at unit level only. Intermediates and Seniors compete together.\\n\\n## Rules\\n- Juniors: Old Testament - Leviticus, Job, Ezekiel. New Testament - Luke, Galatians, Ephesians.\\n- Intermediates and Seniors: Old Testament - Leviticus, Job, Ezekiel. New Testament - Luke, Galatians, Ephesians, Philippians, Colossians, 1 Thessalonians, 2 Thessalonians.\\n- Intermediates and Seniors: Church History - AD 1654 to AD 1816, both years included, from 'The Orthodox Church of India' by David Daniel.\\n- Intermediates and Seniors: Worship and Sacraments - Sacraments of Anointing of the Sick and Qandilo, from MOC Publications books (Koodaasa Kramangal, Order of the Sacraments, Kantheela Susroosha kramam, Order of the Anointing of the sick known as the service of Qandilo, Susroosha samvidhaana sahaayi) and Sunday School Textbook (OSSAE) Class XII ND Chapter 5.\\n- Intermediates and Seniors: Feasts and Church Calendar - Epiphany (Denaha), from Aandu Thaksa - Perunnal Susroosha kramam, Order of the Prayers of the Major Feasts, Susroosha samvidhaana sahaayi (MOC Publications) and Sunday School Textbook (OSSAE) Class XII ND Chapter 9.\\n- Reference Bible: The Holy Bible (NRSV Catholic Edition)."}]`),l=[],r=[{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to register",Value:"2026-04-10",Source:"Circular p.1"},{Key:"AgeCutoffDate",Kind:"date",Label:"Date on which age is counted",Value:"2026-09-30",Source:"Circular p.1, Age Grouping"},{Key:"AttendanceDate",Kind:"date",Label:"Date for the 60 percent attendance check",Value:"2026-06-28",Source:"Circular p.4, rule 1e"},{Key:"DayColouring",Kind:"date",Label:"Day 1: Colouring, Drawing & Colouring, Memory Verse Writing",Value:"2026-04-19",Source:"Circular p.1"},{Key:"DayAction",Kind:"date",Label:"Day 2: Action Song, Story Telling, Bible Reading",Value:"2026-04-26",Source:"Circular p.1"},{Key:"DayElocution",Kind:"date",Label:"Day 3: Elocution and Extempore Speech",Value:"2026-05-10",Source:"Circular p.1"},{Key:"DaySong",Kind:"date",Label:"Day 4: Solo and Group Song",Value:"2026-06-14",Source:"Circular p.1"},{Key:"DayQuiz",Kind:"date",Label:"Day 5: Bible Quiz",Value:"2026-06-28",Source:"Circular p.1"},{Key:"TimeAfternoon",Kind:"time",Label:"Time on days 1 and 2",Value:"1:00 pm to 4:30 pm",Source:"Circular p.1"},{Key:"TimeMorning",Kind:"time",Label:"Start time on days 3 and 4",Value:"11:00 am onwards",Source:"Circular p.1"},{Key:"TimeQuizStart",Kind:"time",Label:"Start time of the quiz",Value:"1:30 pm onwards",Source:"Circular p.1"},{Key:"ZonalMonth",Kind:"text",Label:"When the UAE level competitions are held",Value:"October 2026",Source:"Circular p.4-5"},{Key:"StoryTopic",Kind:"text",Label:"Story Telling topic (Juniors)",Value:"The Tower of Babel (Genesis 11:1-9)",Source:"Circular p.2, Syllabus 3"},{Key:"MemoryVerseList",Kind:"link",Label:"List of 500 memory verses",Value:"https://www.gulfparumala.com/cultural_competitions/Ry",Source:"Circular p.6"}],s=[{Claim:"All rules, schedule, age grouping and syllabus captured from the unit's 2026 circular.",SourceType:"Primary - the event's own rules document",Source:"St. Gregorios Orthodox Church Sunday School, Sharjah - Annual Competitions 2026",Url:"https://gulfparumala.com/storage/datafolder/ckeditorimage/Competition%20Info-Rev_1773775026.pdf"}],d={TemplateKey:e,Year:2026,Note:n,Page:o,ParticipantTypes:t,AgeGroups:i,Competitions:a,CompetitionAgeGroups:l,Variables:r,Evidence:s};export{i as AgeGroups,l as CompetitionAgeGroups,a as Competitions,s as Evidence,n as Note,o as Page,t as ParticipantTypes,e as TemplateKey,r as Variables,u as Year,d as default};
